insert into sector_profiles (settore, version, status, pack, changelog)
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('parrucchiere', 1, 'production', 'info_trattamenti', 'Che differenza c''è tra balayage e shatush?', $qgik96w$["differenza tra balayage e shatush","differenza fra balayage e shatush","balayage o shatush","che differenza ce tra shatush e balayage","meglio balayage o shatush"]$qgik96w$::jsonb, 'Sono due tecniche di schiaritura che danno un effetto naturale. Il balayage è fatto a mano, con pennellate morbide e luce che parte dalle lunghezze; lo shatush crea un effetto più sfumato e "spettinato", con radice più scura. Quale sia più adatto dipende dai suoi capelli e dal risultato che desidera: lo valuta il parrucchiere.', $quurxzp${}$quurxzp$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('parrucchiere', 1, 'production', 'info_trattamenti', 'Cos''è il balayage?', $q49vp9p$["cos e il balayage","cosa e il balayage","in cosa consiste il balayage","come funziona il balayage"]$q49vp9p$::jsonb, 'Il balayage è una tecnica di colorazione in cui il colore viene applicato a mano, con pennellate, per ottenere schiariture naturali e sfumate. Il risultato finale dipende dal colore di partenza dei capelli.', $qal8ql1${}$qal8ql1$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('parrucchiere', 1, 'production', 'info_trattamenti', 'Cos''è lo shatush?', $qra5t66$["cos e lo shatush","cosa e lo shatush","in cosa consiste lo shatush","come funziona lo shatush"]$qra5t66$::jsonb, 'Lo shatush è una tecnica di schiaritura che lascia la radice più scura e illumina le lunghezze in modo sfumato, con un effetto naturale. Il parrucchiere valuta se è adatto ai suoi capelli.', $q7hpd6j${}$q7hpd6j$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('parrucchiere', 1, 'production', 'info_trattamenti', 'Che differenza c''è tra meches, colpi di sole e balayage?', $q9xlfuh$["differenza tra meches e colpi di sole","meches o balayage","colpi di sole o balayage","che differenza ce tra meches e balayage"]$q9xlfuh$::jsonb, 'Meches e colpi di sole sono ciocche schiarite in modo più marcato e regolare; il balayage è più sfumato e naturale. La scelta dipende dallo stile che desidera e dai suoi capelli.', $qm1q0ld${}$qm1q0ld$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('parrucchiere', 1, 'production', 'info_trattamenti', 'Ogni quanto si fa la ricrescita?', $qmg6dsg$["ogni quanto fare la ricrescita","ogni quanto si ritocca la tinta","ogni quanto devo rifare le radici","ogni quanto va fatta la ricrescita","ogni quanto si fa la tinta"]$qmg6dsg$::jsonb, 'In genere il ritocco delle radici si fa ogni quattro-sei settimane, ma dipende da quanto cresce il capello, dal colore scelto e da quanto si nota lo stacco. Il parrucchiere può consigliarle la frequenza più adatta.', $qd92n0v${}$qd92n0v$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('parrucchiere', 1, 'production', 'info_trattamenti', 'Ogni quanto è bene tagliare o spuntare i capelli?', $qpnxznc$["ogni quanto si taglia i capelli","ogni quanto devo spuntare i capelli","ogni quanto va fatta la spuntatina","ogni quanto taglio i capelli"]$qpnxznc$::jsonb, 'Per mantenere la forma e tenere sotto controllo le doppie punte si consiglia in genere una spuntatina ogni due o tre mesi, ma dipende dal taglio e dalla velocità di crescita dei suoi capelli.', $qmbhodl${}$qmbhodl$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('parrucchiere', 1, 'production', 'info_trattamenti', 'Quanto dura una tinta o un colore?', $q8l4xov$["quanto dura la tinta","quanto tempo ci vuole per la tinta","quanto dura il colore","quanto tempo ci vuole per fare il colore"]$q8l4xov$::jsonb, 'I tempi dipendono da lunghezza e quantità dei capelli e dal tipo di lavoro: un ritocco delle radici richiede meno tempo di un colore completo, e le schiariture richiedono più tempo. Il salone le dirà la durata prevista per il suo caso.', $qojbxln${}$qojbxln$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('parrucchiere', 1, 'production', 'info_trattamenti', 'Quanto dura un''appuntamento per le schiariture?', $qrfrb3i$["quanto dura il balayage","quanto dura lo shatush","quanto tempo ci vuole per le meches","quanto dura una seduta di schiariture","quanto tempo ci vuole per il balayage"]$qrfrb3i$::jsonb, 'Le schiariture sono tra i servizi più lunghi: possono servire diverse ore, in base a lunghezza, densità dei capelli e risultato desiderato. Per una stima precisa conviene chiedere al salone.', $q03nm12${}$q03nm12$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('parrucchiere', 1, 'production', 'info_trattamenti', 'Quanto dura l''effetto della piega?', $q5gn77x$["quanto dura la piega","per quanto tempo dura la piega","quanto resiste la piega","quanto tiene la piega"]$q5gn77x$::jsonb, 'La piega dura qualche giorno: dipende dal tipo di capello, dall''umidità e da come lo si tratta. Il parrucchiere può darle consigli per farla durare di più.', $qrbsw8a${}$qrbsw8a$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('parrucchiere', 1, 'production', 'info_trattamenti', 'Cos''è la cheratina e quanto dura?', $q7r0elq$["cos e la cheratina","come funziona la cheratina","quanto dura la cheratina","in cosa consiste la stiratura","cos e la stiratura","quanto resiste la cheratina"]$q7r0elq$::jsonb, 'Il trattamento alla cheratina o la stiratura rende i capelli più lisci, disciplinati e lucidi, riducendo il crespo. L''effetto è temporaneo e la durata dipende dai capelli, dal prodotto e dalla cura che se ne ha dopo; il parrucchiere valuta se è adatto al suo caso.', $qhsqdhi${}$qhsqdhi$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('parrucchiere', 1, 'production', 'info_trattamenti', 'La decolorazione rovina i capelli?', $qbgtqnp$["la decolorazione rovina i capelli","decolorare rovina i capelli","schiarire rovina i capelli","le meches rovinano i capelli","il balayage rovina i capelli"]$qbgtqnp$::jsonb, 'Schiarire i capelli li stressa, perché il pigmento viene rimosso con prodotti chimici. Con tecnica corretta, trattamenti di cura e un buon punto di partenza lo stress si limita, ma l''effetto dipende dallo stato dei capelli: lo valuta il parrucchiere.', $qh4jqak${}$qh4jqak$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('parrucchiere', 1, 'production', 'info_trattamenti', 'Quante sedute servono per schiarire molto i capelli?', $qnowb7d$["quante sedute servono per diventare biondi","si diventa biondi in una volta","quante sedute per schiarire","posso diventare biondo platino subito","quante schiariture servono"]$qnowb7d$::jsonb, 'Dipende dal colore di partenza e dallo stato dei capelli. Per schiarire molto, e preservare i capelli, a volte si procede in più passaggi graduali: il parrucchiere ne parla in consulenza e non può garantire un risultato in una sola volta.', $qid8bel${}$qid8bel$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('parrucchiere', 1, 'production', 'info_trattamenti', 'Cos''è il trattamento ricostruttivo?', $qwb0rkz$["cos e il trattamento ricostruttivo","come funziona la ricostruzione","a cosa serve la ricostruzione","cos e la ricostruzione dei capelli","cosa sono i trattamenti ricostruttivi"]$qwb0rkz$::jsonb, 'Il trattamento ricostruttivo serve a rinforzare e nutrire i capelli stressati da colore, schiariture o calore. Esistono prodotti e metodi diversi: il parrucchiere sceglie quello più adatto in base allo stato dei capelli.', $qirudod${}$qirudod$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('parrucchiere', 1, 'production', 'info_trattamenti', 'Cos''è la permanente?', $qq0ckuv$["cos e la permanente","come funziona la permanente","in cosa consiste la permanente","quanto dura la permanente"]$qq0ckuv$::jsonb, 'La permanente è un trattamento chimico che modifica la forma dei capelli per ottenere onde o ricci che durano nel tempo, finché non crescono i capelli nuovi. Il parrucchiere valuta se è adatta ai suoi capelli.', $qljsfx7${}$qljsfx7$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('parrucchiere', 1, 'production', 'info_trattamenti', 'Cosa sono le extension?', $qf7098i$["cosa sono le extension","come funzionano le extension","cos e l extension","che tipi di extension esistono","le extension rovinano i capelli"]$qf7098i$::jsonb, 'Le extension sono ciocche aggiuntive che danno lunghezza o volume. Esistono metodi di applicazione diversi (per esempio a clip o fissate in altri modi): serve una consulenza per scegliere quello adatto ai suoi capelli e a come intende usarle.', $qw8iwl2${}$qw8iwl2$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('parrucchiere', 1, 'production', 'info_trattamenti', 'Si possono coprire i capelli bianchi?', $q2wgumk$["si coprono i capelli bianchi","la tinta copre i capelli bianchi","come si coprono i bianchi","posso coprire i bianchi","come coprire i capelli bianchi"]$q2wgumk$::jsonb, 'Sì, in genere con una colorazione si coprono i capelli bianchi. La resa dipende da quanti sono, dal tono scelto e dal tipo di capello: lo stilista consiglia la soluzione migliore.', $qq4lrd4${}$qq4lrd4$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('parrucchiere', 1, 'production', 'info_trattamenti', 'Posso fare colore e taglio nello stesso appuntamento?', $q3x3wsz$["posso fare tinta e taglio insieme","si puo fare taglio e colore insieme","colore e taglio nello stesso giorno","posso fare colore e piega insieme"]$q3x3wsz$::jsonb, 'In genere sì: più servizi si possono combinare nello stesso appuntamento, purché ci sia il tempo necessario. Le conviene indicarli tutti al momento della prenotazione.', $q4chr3j${}$q4chr3j$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('parrucchiere', 1, 'production', 'info_trattamenti', 'Posso fare la tinta se ho i capelli rovinati?', $qudumoo$["posso fare la tinta con i capelli rovinati","posso schiarire se i capelli sono rovinati","capelli rovinati posso colorare","posso colorare capelli sfibrati"]$qudumoo$::jsonb, 'Dipende dallo stato dei capelli: il parrucchiere li valuta prima di decidere se procedere subito oppure fare prima un trattamento di cura. Meglio non improvvisare con prodotti fai da te.', $qps99jr${}$qps99jr$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('parrucchiere', 1, 'production', 'info_trattamenti', 'Dopo la tinta o la cheratina quando posso lavare i capelli?', $q0zcrk7$["quando posso lavare i capelli dopo la tinta","dopo la cheratina quanto aspetto per lavare i capelli","posso lavare i capelli dopo la tinta","quando lavo i capelli dopo il trattamento"]$q0zcrk7$::jsonb, 'Dipende dal prodotto e dal trattamento: il salone le darà le indicazioni precise per il suo caso, da seguire con attenzione. Per dubbi particolari contatti direttamente il salone.', $qtkdqpq${}$qtkdqpq$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('parrucchiere', 1, 'production', 'info_trattamenti', 'Posso fare lo shatush o il balayage sui capelli corti?', $qg79yx9$["balayage su capelli corti","shatush su capelli corti","si puo fare lo shatush sui capelli corti","le meches su capelli corti"]$qg79yx9$::jsonb, 'Dipende da lunghezza e taglio: su capelli corti si possono ottenere effetti di schiaritura, ma il risultato è diverso da quello su capelli lunghi. Il parrucchiere valuta in consulenza la tecnica più adatta.', $qrv6q9m${}$qrv6q9m$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('parrucchiere', 1, 'production', 'info_trattamenti', 'Ogni quanto si regola la barba?', $qazy0cy$["ogni quanto va regolata la barba","ogni quanto si fa la barba dal barbiere","ogni quanto fare la rifinitura della barba"]$qazy0cy$::jsonb, 'Dipende dalla velocità di crescita e dalla forma che si vuole mantenere: in genere ogni due o tre settimane per tenerla in ordine. Il barbiere può darle un consiglio personalizzato.', $qeqpu52${}$qeqpu52$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('parrucchiere', 1, 'production', 'info_preparazione', 'Posso portare una foto di riferimento?', $qepq6kt$["posso portare foto di riferimento","posso mandarvi una foto del colore che voglio","vi mando una foto","posso inviare una foto del taglio","serve una foto di riferimento"]$qepq6kt$::jsonb, 'Sì, una foto di riferimento è molto utile per capire il risultato che desidera. Poi il parrucchiere valuta cosa è realizzabile sui suoi capelli.', $qiti3tv${}$qiti3tv$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('parrucchiere', 1, 'production', 'info_preparazione', 'Devo venire con i capelli lavati?', $q414qj5$["devo lavare i capelli prima","posso venire con i capelli sporchi","devo venire con i capelli puliti","capelli sporchi o puliti"]$q414qj5$::jsonb, 'Dipende dal servizio: per alcuni trattamenti si preferisce una cute non appena lavata, per altri è indifferente. Il salone le darà l''indicazione giusta per il suo appuntamento.', $qf77f9b${}$qf77f9b$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('parrucchiere', 1, 'production', 'info_preparazione', 'Cos''è il patch test e serve prima della tinta?', $qg5zg3s$["serve il patch test","cos e il patch test","si fa il test allergia","devo fare il test allergia prima della tinta","quando si fa il patch test","test di sensibilita tinta"]$qg5zg3s$::jsonb, 'Il patch test, o test di sensibilità, è una piccola prova del prodotto sulla pelle che viene proposta prima di alcuni trattamenti di colore. Come e quando farlo lo indica il salone; in caso di allergie note o dubbi è bene parlarne anche con il proprio medico.', $q790sz9${}$q790sz9$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('parrucchiere', 1, 'production', 'info_preparazione', 'Posso portare i miei prodotti?', $q4wbz88$["posso portare la mia tinta","posso portare i miei prodotti da casa","posso usare la mia tinta","vi porto io i prodotti"]$q4wbz88$::jsonb, 'Conviene chiedere al salone: di norma ogni salone lavora con i propri prodotti e decide se e come usare quelli del cliente.', $q0y5zrd${}$q0y5zrd$::jsonb);
insert into sector_test_scenarios (settore, codice, categoria, scenario) values ('parrucchiere', 'PA01', 'BOOKING', $qefesaf${"scenario":{"input":"Buongiorno, vorrei prenotare una piega","expected":{"intent":"prenota_servizio","entities":{"servizio":"piega"},"action":"ask_missing_information","next_question":"nome_cliente","safety":"LOW"},"tenant":{"campi":["nome_cliente"],"haCalendario":true,"info_generali":{"indirizzo":"via dei tigli 18","prezzi_note":"taglio donna da 30 euro, piega da 20 euro, colore da 45 euro","altre_informazioni":"parcheggio gratuito, accettiamo carte e contanti, chiuso il lunedi"}}}}$qefesaf$::jsonb) on conflict (settore, codice) do update set categoria = excluded.categoria, scenario = excluded.scenario;
